// PROCESS: expects msg.payload as an object (after JSON node)

// ---------- 1) Normalize input payload ----------
var p = msg.payload || {};

// free slots (0..3)
var free = Number(p.free);
if (isNaN(free)) free = 0;
if (free < 0) free = 0;
if (free > 3) free = 3;

// occupied slots (0..3)
var occ = 3 - free;
if (occ < 0) occ = 0;
if (occ > 3) occ = 3;

// timestamp (ms)
var ts = Date.now();

// slots as bitstring (e.g., 110)
var slotsStr = "";
if (Array.isArray(p.slots)) {
    slotsStr = String(p.slots.join(""));
}

// entrance / exit events (0/1)
var ent = Number(p.entrance);
if (isNaN(ent)) ent = 0;

var ex = Number(p.exit);
if (isNaN(ex)) ex = 0;

// barrier state
var bar = (p.barrier !== undefined) ? String(p.barrier) : "UNKNOWN";

// topic for classification and traceability
var topic = msg.topic || "";

// ---------- 2) Scenario classification (LOCKED by topic names) ----------
var scenario = "UNKNOWN";
if (topic.indexOf("slots-sim-nonsec") >= 0) scenario = "S1";
else if (topic.indexOf("slots-sim-sec") >= 0) scenario = "S2";
else if (topic.indexOf("slots-hw-nonsec") >= 0) scenario = "S3";
else if (topic.indexOf("slots-hw-sec") >= 0) scenario = "S4";

// Security mode label
var modeText = "UNKNOWN";
if (scenario === "S1" || scenario === "S3") modeText = "NON-SECURE";
else if (scenario === "S2" || scenario === "S4") modeText = "SECURE (TLS)";

// utilization (0..1)
var util = occ / 3;

// ---------- 3) AI latency (ms) from inference branch ----------
// Latency is produced in the HTTP response path and stored in flow context.
// Attach it only if it is "fresh" (e.g., within the last 5 seconds).

var ai_latency = -1;  // IMPORTANT: default value when inference did not occur

var lastLat = flow.get("last_ai_latency_ms");
var lastTs = flow.get("last_ai_latency_ts");

if (lastLat !== undefined && lastLat !== null && lastTs !== undefined) {
    var age = Date.now() - Number(lastTs);
    if (!isNaN(age) && age >= 0 && age <= 5000) {   // 5s freshness window
        ai_latency = Number(lastLat);
        if (isNaN(ai_latency)) ai_latency = -1;
    }
}

// ---------- 4) Attach meta object (dashboard + switch + logging) ----------
// CSV schema (LOCKED):
// epoch_ms,slots_bits,occ,free,entrance_event,exit_event,barrier,ai_latency_ms,scenario,mode,topic
var csvRow =
    ts + "," +
    slotsStr + "," +
    occ + "," +
    free + "," +
    ent + "," +
    ex + "," +
    bar + "," +
    ai_latency + "," +
    scenario + "," +
    modeText + "," +
    topic;

msg.meta = msg.meta || {};

msg.meta.scenario = scenario;
msg.meta.mode = modeText;
msg.meta.free = free;
msg.meta.occ = occ;
msg.meta.util = util;
msg.meta.ai_latency_ms = ai_latency;
msg.meta.csv = csvRow;

// Keep these for any existing UI nodes that use msg.free/msg.occ/msg.util
msg.free = free;
msg.occ = occ;
msg.util = util;

// Do NOT overwrite msg.payload (preserves downstream compatibility)

// ---------- 5) Build Azure features (DETERMINISTIC, demo-stable) ----------
// Model expects 6 features:
// slot{i}_occupied_ratio, slot{i}_event_rate

var slotsArr = Array.isArray(p.slots) ? p.slots : [0, 0, 0]; // 1=OCCUPIED, 0=FREE

function occ01(v) { return (Number(v) === 1) ? 1 : 0; } // occupied -> 1

var o1 = occ01(slotsArr[0]);
var o2 = occ01(slotsArr[1]);
var o3 = occ01(slotsArr[2]);

// Use entrance/exit events as activity signals (0/1)
var e1 = ent;                 // entrance event
var e2 = ex;                  // exit event
var e3 = (ent || ex) ? 1 : 0; // any event

msg.features = {
    slot1_occupied_ratio: o1,
    slot2_occupied_ratio: o2,
    slot3_occupied_ratio: o3,
    slot1_event_rate: e1,
    slot2_event_rate: e2,
    slot3_event_rate: e3
};
return msg;

msg.topic = "occupied";
msg.payload = Number(msg.occ ?? (3 - (msg.payload?.free ?? 0)));
return msg;

// Controlled S5-S7 preprocessing.
// Same frozen telemetry -> same six AI features.
//
// All time-dependent AI features use the ORIGINAL
// source timestamp rather than host wall-clock time.

msg.meta = msg.meta || {};

const p = msg.payload || {};

const slots =
    Array.isArray(p.slots)
        ? p.slots
        : [0, 0, 0];


// ------------------------------------------------------------
// 1. Frozen source identity/time
// ------------------------------------------------------------

const sourceTs = Number(
    msg.meta.source_epoch_ms !== undefined
        ? msg.meta.source_epoch_ms
        : (
            p.source_epoch_ms !== undefined
                ? p.source_epoch_ms
                : p.ts
        )
);

const replaySeq = Number(
    msg.meta.replay_seq !== undefined
        ? msg.meta.replay_seq
        : p.replay_seq
);

if (!Number.isFinite(sourceTs)) {
    node.error(
        "Missing/invalid source timestamp",
        msg
    );
    return null;
}


// ------------------------------------------------------------
// 2. Sliding-window state
// ------------------------------------------------------------

const W = 10;

let hist =
    flow.get("slot_hist") ||
    [[], [], []];

let last =
    flow.get("slot_last") ||
    [null, null, null];

let flips =
    flow.get("slot_flips") ||
    [0, 0, 0];

let flipT0 =
    Number(
        flow.get("flip_t0")
    );


// ------------------------------------------------------------
// 3. Explicit run-boundary reset
// ------------------------------------------------------------

if (
    replaySeq === 1 ||
    !Array.isArray(hist) ||
    !Array.isArray(last) ||
    !Array.isArray(flips) ||
    !Number.isFinite(flipT0) ||
    sourceTs < flipT0
) {
    hist = [[], [], []];
    last = [null, null, null];
    flips = [0, 0, 0];
    flipT0 = sourceTs;
}


// ------------------------------------------------------------
// 4. Update occupancy history and flip counters
// ------------------------------------------------------------

for (let i = 0; i < 3; i++) {

    // Normalized replay semantics:
    // 1 = OCCUPIED
    // 0 = FREE

    const v =
        Number(slots[i]) === 1
            ? 1
            : 0;

    if (
        last[i] !== null &&
        v !== last[i]
    ) {
        flips[i] += 1;
    }

    last[i] = v;

    hist[i].push(v);

    if (hist[i].length > W) {
        hist[i].shift();
    }
}


// ------------------------------------------------------------
// 5. Occupancy-ratio features
// ------------------------------------------------------------

function mean(arr) {

    if (
        !arr ||
        arr.length === 0
    ) {
        return 0;
    }

    return (
        arr.reduce(
            (a, b) => a + b,
            0
        ) / arr.length
    );
}

const r1 =
    Number(
        mean(hist[0]).toFixed(3)
    );

const r2 =
    Number(
        mean(hist[1]).toFixed(3)
    );

const r3 =
    Number(
        mean(hist[2]).toFixed(3)
    );


// ------------------------------------------------------------
// 6. Deterministic event-rate features
//
// Definition preserved:
//     flips / elapsed seconds
//
// Elapsed time now comes from source_epoch_ms.
// ------------------------------------------------------------

let dt =
    (
        sourceTs -
        flipT0
    ) / 1000.0;

if (dt < 0) {
    dt = 0;
}

let er1 = 0;
let er2 = 0;
let er3 = 0;

if (dt >= 1.0) {

    er1 =
        Number(
            (flips[0] / dt)
            .toFixed(3)
        );

    er2 =
        Number(
            (flips[1] / dt)
            .toFixed(3)
        );

    er3 =
        Number(
            (flips[2] / dt)
            .toFixed(3)
        );

    flipT0 = sourceTs;

    flips = [0, 0, 0];
}


// ------------------------------------------------------------
// 7. Store deterministic state
// ------------------------------------------------------------

flow.set(
    "slot_hist",
    hist
);

flow.set(
    "slot_last",
    last
);

flow.set(
    "slot_flips",
    flips
);

flow.set(
    "flip_t0",
    flipT0
);


// ------------------------------------------------------------
// 8. Final six model features
// ------------------------------------------------------------

msg.features = {

    slot1_occupied_ratio: r1,
    slot2_occupied_ratio: r2,
    slot3_occupied_ratio: r3,

    slot1_event_rate: er1,
    slot2_event_rate: er2,
    slot3_event_rate: er3
};


// ------------------------------------------------------------
// 9. FastAPI request body
// ------------------------------------------------------------

msg.payload = {
    features: msg.features
};

msg.headers =
    msg.headers || {};

msg.headers["Content-Type"] =
    "application/json";

return msg;

// Handle Azure Response (LOCKED)
// Parses Azure response, sets msg.ai.prediction consistently, never redeclares variables.

let r = msg.payload;

// Parse if needed
if (typeof r === "string") {
    try { r = JSON.parse(r); } catch(e) { r = {}; }
}
if (!r || typeof r !== "object") r = {};

msg.ai = msg.ai || {};

// If API returns {"detail":"Not Found"} or validation error
if (r.detail) {
    msg.ai.prediction = "AI_ERR";
    msg.ai.recommendation = "Cloud AI unavailable. Using sensor-only status.";
    msg.ai.raw = r;
    return msg;
}

// Normal success path
msg.ai.prediction = (r.prediction !== undefined) ? String(r.prediction).toUpperCase() : "UNKNOWN";
msg.ai.probabilities = r.probabilities || {};
msg.ai.utilization = (r.utilization !== undefined) ? r.utilization : undefined;
msg.ai.raw = r;

return msg;

// Prediction / AI behavior log (NOT timing)

const s = msg.azure_summary || {};
const now = new Date().toISOString();

// CSV columns:
// timestamp, lot_id, total_free, total_occupied, slots_count,
// utilization_pct, status, recommendation
const line = [
  now,
  s.lot_id ?? "",
  s.total_free ?? "",
  s.total_occupied ?? "",
  s.slots_count ?? "",
  s.utilization_pct ?? "",
  s.status ?? "",
  '"' + String(s.recommendation ?? "").replace(/"/g, '""') + '"'
].join(",") + "\n";

msg.payload = line;
return msg;

// Append-only training row for the SAME 6 features Azure expects

const f = msg.features || {};
const util = Number(msg.util ?? msg.meta?.util ?? 0);

// label from utilization (your rule)
let label = "NORMAL";
if (util >= 0.8) label = "CRITICAL";
else if (util >= 0.5) label = "BUSY";

// CSV columns in order expected by retrain script
// timestamp, slot1_occ_ratio, slot2_occ_ratio, slot3_occ_ratio, slot1_event_rate, slot2_event_rate, slot3_event_rate, label
msg.payload = [
  new Date().toISOString(),
  Number(f.slot1_occupied_ratio ?? 0),
  Number(f.slot2_occupied_ratio ?? 0),
  Number(f.slot3_occupied_ratio ?? 0),
  Number(f.slot1_event_rate ?? 0),
  Number(f.slot2_event_rate ?? 0),
  Number(f.slot3_event_rate ?? 0),
  label
].join(",") + "\n";

return msg;

const perf = global.get("perf");

msg.meta = msg.meta || {};

// Preserve frozen-workload identity for experimental traceability.
// These fields do NOT affect AI preprocessing or inference.
const replayPayload =
    (msg.payload && typeof msg.payload === "object")
    ? msg.payload : {};

msg.meta.replay_seq =
    (replayPayload.replay_seq !== undefined)
    ? replayPayload.replay_seq : "";

msg.meta.source_line =
    (replayPayload.source_line !== undefined)
    ? replayPayload.source_line : "";

msg.meta.source_epoch_ms =
    (replayPayload.source_epoch_ms !== undefined)
    ? replayPayload.source_epoch_ms :
    ((replayPayload.ts !== undefined) ? replayPayload.ts : "");

msg.meta.raw_slots_bits =
    (replayPayload.raw_slots_bits !== undefined)
    ? replayPayload.raw_slots_bits : "";

msg.meta.t0 = Date.now();
msg.meta.t0_mono = perf.now();

const t = (msg.topic || "").toLowerCase();
if (t.includes("nonsec")) msg.meta.mode = "nonsecure";
else if (t.includes("sec")) msg.meta.mode = "secure";
else msg.meta.mode = "unknown";

msg.meta.gt_occ = (typeof msg.occ === "number") ? msg.occ : null;
msg.meta.gt_free = (typeof msg.free === "number") ? msg.free : null;

msg.meta.run_id =
    flow.get("run_id") ||
    ("run_" + new Date().toISOString().slice(0,10));

return msg;

// Stop Timer + Build Log Record (AFTER HTTP response)
const perf = global.get("perf");

msg.meta = msg.meta || {};
msg.meta.t1 = Date.now();

const t1_mono = perf.now();
msg.meta.latency_ms =
    (typeof msg.meta.t0_mono === "number")
    ? Number((t1_mono - msg.meta.t0_mono).toFixed(3))
    : null;

msg.meta.ai_latency_ms = msg.meta.latency_ms;

flow.set("last_ai_latency_ms", msg.meta.ai_latency_ms);
flow.set("last_ai_latency_ts", msg.meta.t1);

const ts = new Date(msg.meta.t1).toISOString();
const sc = msg.statusCode || "";
const resp = msg.payload || {};

const prediction =
    (resp.prediction !== undefined) ? resp.prediction : "";
const probs =
    (resp.probabilities !== undefined)
    ? JSON.stringify(resp.probabilities) : "";
const recommendation =
    (resp.recommendation !== undefined)
    ? String(resp.recommendation) : "";

msg.ai_inference_csv = [
  ts,
  msg.meta.run_id || "",
  msg.meta.mode || "",
  sc,
  msg.meta.latency_ms ?? "",
  msg.meta.gt_occ ?? "",
  msg.meta.gt_free ?? "",
  prediction
].join(",");

msg.ai_prediction_csv = [
  ts,
  msg.meta.run_id || "",
  msg.meta.mode || "",
  prediction,
  '"' + recommendation.replace(/"/g,'""') + '"',
  '"' + probs.replace(/"/g,'""') + '"'
].join(",");

return msg;

msg.headers = msg.headers || {};
msg.headers["Content-Type"] = "application/json";
msg.headers["x-api-key"] = "StrongPass123";
return msg;

// Deterministic inference-request selection.
//
// Admit one telemetry item at each 1000-ms boundary
// measured from the frozen source trace.

msg.meta = msg.meta || {};

const ts =
    Number(
        msg.meta.source_epoch_ms
    );

const seq =
    Number(
        msg.meta.replay_seq
    );

if (!Number.isFinite(ts)) {
    node.error(
        "Missing source_epoch_ms for deterministic sampler",
        msg
    );
    return null;
}

let t0 =
    Number(
        flow.get(
            "det_inference_sampler_t0"
        )
    );

let k =
    Number(
        flow.get(
            "det_inference_sampler_k"
        )
    );


// Explicit replay reset.

if (
    seq === 1 ||
    !Number.isFinite(t0) ||
    !Number.isFinite(k) ||
    ts < t0
) {
    t0 = ts;
    k = 0;
}


const target =
    t0 + (k * 1000);


// First telemetry packet at or after each source-time
// 1-second boundary is admitted.

if (ts >= target) {

    do {
        k += 1;
    }
    while (
        t0 + (k * 1000) <= ts
    );

    flow.set(
        "det_inference_sampler_t0",
        t0
    );

    flow.set(
        "det_inference_sampler_k",
        k
    );

    return msg;
}


flow.set(
    "det_inference_sampler_t0",
    t0
);

flow.set(
    "det_inference_sampler_k",
    k
);

return null;

msg.debug_line = {
  statusCode: msg.statusCode,
  responseUrl: msg.responseUrl,
  payload: msg.payload
};
return msg;

const t = msg.topic || "";

let scenario = "UNK";
if (t.includes("sim-nonsec")) scenario = "S1";
else if (t.includes("sim-sec")) scenario = "S2";
else if (t.includes("hw-nonsec")) scenario = "S3";
else if (t.includes("hw-sec")) scenario = "S4";

msg.meta = msg.meta || {};
msg.meta.scenario = scenario;
msg.meta.mode = (scenario === "S2" || scenario === "S4") ? "SECURE (TLS)" : "NON-SECURE";

return msg;

const active = flow.get("activeScenario") || "ALL";
const s = (msg.meta && msg.meta.scenario) ? msg.meta.scenario : "UNK";

// show live status so we know gate is receiving messages
node.status({fill:"blue",shape:"dot",text:`active=${active} got=${s}`});

// If you want to *debug* without dropping anything, set PASS_ALL=true
const PASS_ALL = false;

if (!PASS_ALL) {
  if (active !== "ALL" && s !== active) return null;
}

return msg;

// Expect msg.payload to be like: "S1", "S2", "S3", "S4", or "ALL"
// If your inject nodes are not sending that yet, fix inject payload (next step).

const s = String(msg.payload || "ALL").trim().toUpperCase();

flow.set("activeScenario", s);

// show selected scenario on the node (helps debugging)
node.status({fill:"green", shape:"dot", text:`activeScenario=${s}`});

// IMPORTANT: do not forward this message to any file/log nodes
return null;

const occ = 3 - Number(msg.payload.free);
msg.payload = (occ / 3) * 100;
return msg;

// Prefer topic-based detection (most reliable)
// Fallback to meta/payload if topic doesn't encode it

const topic = (msg.topic || "").toLowerCase();
const metaMode = (msg.meta?.mode || "").toString().toLowerCase();
const payloadMode = (msg.payload?.mode || msg.payload?.security || "").toString().toLowerCase();

function isSecure(s) {
    return s.includes("sec") && !s.includes("non");
}
function isNonSecure(s) {
    return s.includes("non") || s.includes("plain") || s.includes("1883");
}

// 1) Detect from topic (preferred)
let secure = false;
let nonsecure = false;

if (topic) {
    secure = isSecure(topic);
    nonsecure = isNonSecure(topic) || topic.includes("nonsec") || topic.includes("non-sec");
}

// 2) Fallback to meta/payload
if (!secure && !nonsecure) {
    secure = isSecure(metaMode) || isSecure(payloadMode);
    nonsecure = isNonSecure(metaMode) || isNonSecure(payloadMode);
}

// 3) Format output
if (secure) {
    msg.payload = "🔒 SECURE (TLS)";
} else if (nonsecure) {
    msg.payload = "🔓 NON-SECURE";
} else {
    msg.payload = "UNKNOWN";
}

return msg;

const now = Date.now();
const sec = Math.floor(now / 1000);
const scenario = msg.meta?.scenario || "UNK";
const key = scenario + ":" + sec;

const lastKey = flow.get("tp_key");
let count = flow.get("tp_count") || 0;

// new second started
if (key !== lastKey) {
  // before reset, log the previous second if it exists
  const prevScenario = (lastKey || "").split(":")[0];
  const prevSec = parseInt((lastKey || "0:0").split(":")[1] || "0", 10);
  const prevCount = count;

  flow.set("tp_key", key);
  flow.set("tp_count", 1);
  msg.tp_mps = 1;

  // emit log for previous second (skip first time)
  if (lastKey) {
    const ts = new Date(prevSec * 1000).toISOString();
    const deployment = (prevScenario === "S1" || prevScenario === "S2") ? "simulation" : "hardware";
    const security = (prevScenario === "S2" || prevScenario === "S4") ? "tls" : "nonsec";

    const logMsg = {
      payload: {
        timestamp: ts,
        scenario: prevScenario,
        deployment,
        security,
        msg_rate: prevCount
      }
    };
    return [msg, logMsg];
  }
  return [msg, null];
}

// same second continues
count += 1;
flow.set("tp_count", count);
msg.tp_mps = count;
return [msg, null];

// Build a friendly label for dashboard (still keep S1..S4 for experiments)
const s = msg.meta?.scenario || "UNK";

let label = "UNKNOWN";
if (s === "S1") label = "S1 (SIM, NON-SECURE)";
else if (s === "S2") label = "S2 (SIM, SECURE/TLS)";
else if (s === "S3") label = "S3 (HW, NON-SECURE)";
else if (s === "S4") label = "S4 (HW, SECURE/TLS)";
else if (s === "ALL") label = "ALL (no gating)";

msg.payload = label;
return msg;

const s = msg.meta?.scenario || "UNK";
const isSecure = (s === "S2" || s === "S4");

if (!isSecure) {
  msg.payload = "TLS: OFF (no certificate)";
  return msg;
}

// Use accurate wording: CA is used by the MQTT client when TLS is enabled
msg.payload = "TLS: ON (CA certificate configured)";
return msg;


const scenario = msg.meta?.scenario || "UNK";

let text = "TLS: UNKNOWN";

if (scenario === "S1" || scenario === "S3") {
    text = "TLS: OFF (no certificate)";
}
else if (scenario === "S2" || scenario === "S4") {
    text = "TLS: ON (CA certificate configured)";
}

msg.payload = text;
return msg;

const scenario = msg.meta?.scenario || "UNK";

let text = "Port: UNKNOWN";

if (scenario === "S1" || scenario === "S3") {
    text = "Port: 1883 (MQTT)";
}
else if (scenario === "S2" || scenario === "S4") {
    text = "Port: 8883 (MQTT over TLS)";
}

msg.payload = text;
return msg;

// All CSV file function (S1–S4 router)
// Purpose:
//  - ensure msg.meta.csv exists (created in PROCESS)
//  - route each message to exactly one output based on msg.meta.scenario
//  - set msg.payload to the CSV line for File nodes

if (!msg.meta || !msg.meta.csv) return [null, null, null, null];

var sc = (msg.meta.scenario !== undefined) ? String(msg.meta.scenario).trim() : "UNKNOWN";

// payload must be the line written by File node
msg.payload = msg.meta.csv;

// Route to one output only
switch (sc) {
    case "S1":
        return [msg, null, null, null];
    case "S2":
        return [null, msg, null, null];
    case "S3":
        return [null, null, msg, null];
    case "S4":
        return [null, null, null, msg];
    default:
        // Unknown scenario -> drop (or route to S1 if you want, but dropping is cleaner)
        return [null, null, null, null];
}

// AI Latency Tap: writes AI latency into flow context for metrics CSV.
// Non-invasive: does not modify msg.payload or msg.meta required by dashboard.

try {
    const lat = (msg.meta && msg.meta.latency_ms !== undefined) ? Number(msg.meta.latency_ms) : null;

    if (lat !== null && !isNaN(lat) && lat >= 0) {
        flow.set("last_ai_latency_ms", lat);
        flow.set("last_ai_latency_ts", (msg.meta && msg.meta.t1) ? msg.meta.t1 : Date.now());
    }
    } catch (e) {}

return msg;

const pred = (msg.ai && msg.ai.prediction) ? String(msg.ai.prediction).toUpperCase() : "UNKNOWN";

let rec = "";
if (pred === "NORMAL") rec = "Parking available. Normal traffic.";
else if (pred === "BUSY") rec = "Moderate congestion. Consider alternate slot/entry.";
else if (pred === "CRITICAL") rec = "Lot near/full. Redirect to nearest parking.";
else rec = "AI unavailable. Using sensor-only status.";

msg.ai = msg.ai || {};
msg.ai.recommendation = rec;
return msg;

// Expect msg.payload is an object (already parsed JSON)
const p = msg.payload || {};
msg.payload = p.barrier || "UNKNOWN";
return msg;

const perf = global.get("perf");

msg.meta = msg.meta || {};

msg.meta.e2e_t0_wall = Date.now();
msg.meta.e2e_t0_mono = perf.now();

return msg;

const p = msg.payload;

if (!p || typeof p !== "object") {
    return null;
}

const timestamp =
    p.timestamp || new Date().toISOString();

const scenario =
    p.scenario || "UNK";

const deployment =
    p.deployment || "";

const security =
    p.security || "";

const rate =
    Number(p.msg_rate);

if (!Number.isFinite(rate)) {
    return null;
}

msg.payload = [
    timestamp,
    scenario,
    deployment,
    security,
    rate
].join(",") + "\n";

return msg;

const ts = new Date().toISOString();
const scenario = flow.get("activeScenario") || "ALL";

// stdout from exec should be "cpu,mem"
const out = (msg.payload || "").toString().trim();
if (!out.includes(",")) return null;

msg.payload = `${ts},${scenario},${out}`;   // file node appends newline
return msg;

const perf = global.get("perf");

msg.meta = msg.meta || {};

const endWall = Date.now();
const endMono = perf.now();

let e2e_ms = "";

if (typeof msg.meta.e2e_t0_mono === "number") {
    e2e_ms = Number(
        (endMono - msg.meta.e2e_t0_mono).toFixed(3)
    );
}

const ts = new Date(endWall).toISOString();

const run_id =
    msg.meta.run_id ||
    flow.get("run_id") ||
    "";

const scenario =
    msg.meta.scenario ||
    flow.get("activeScenario") ||
    "UNK";

const mode =
    msg.meta.mode || "unknown";

const ai_ms =
    (msg.meta.ai_latency_ms !== undefined &&
     msg.meta.ai_latency_ms !== null)
    ? msg.meta.ai_latency_ms
    : (flow.get("last_ai_latency_ms") ?? "");

msg.meta.e2e_latency_ms = e2e_ms;

// IMPORTANT:
// The next node expects msg.e2e_csv_line.
// Do NOT add \n because the File node already appends newline.
msg.e2e_csv_line = [
    ts,
    run_id,
    scenario,
    mode,
    e2e_ms,
    ai_ms
].join(",");

return msg;

// AI Hold + Worst-Across-Streams (LOCKED)
// - Never returns null (so UI cannot be overwritten by other paths)
// - Holds worst label for HOLD_MS even if later NORMAL arrives
// - Works across multiple topics (sim/hw, sec/nonsec)

const HOLD_MS = 30000; // 30s (stable). You can reduce later to 15000.
const sev = { NORMAL: 0, BUSY: 1, CRITICAL: 2 };
const now = Date.now();

// Read incoming prediction if present
const incomingRaw = (msg.ai?.prediction ?? msg.payload?.prediction ?? null);
const incoming = incomingRaw ? String(incomingRaw).toUpperCase() : null;

// Load hold state
let held = flow.get("ai_held_label") || "NORMAL";
let heldTs = flow.get("ai_held_ts") || 0;

// Update hold state only if incoming is valid label
if (incoming && (incoming in sev)) {
  // If upgrade or same severity -> accept immediately and reset timer
  if (sev[incoming] >= sev[held]) {
    held = incoming;
    heldTs = now;
  } else {
    // downgrade only if hold time expired
    if ((now - heldTs) >= HOLD_MS) {
      held = incoming;
      heldTs = now;
    }
  }
}

// Persist hold state
flow.set("ai_held_label", held);
flow.set("ai_held_ts", heldTs);

// FORCE outgoing prediction to held label (always)
msg.ai = msg.ai || {};
msg.ai.prediction = held;

// Optional debug fields (won’t affect UI)
msg.ai._incoming = incoming;
msg.ai._held_age_ms = now - heldTs;

return msg;

// Dedicated S6 experiment logger.
// This branch does not modify the legacy AI logs.

const resp =
    (msg.payload && typeof msg.payload === "object")
    ? msg.payload : {};

const probs =
    (resp.probabilities && typeof resp.probabilities === "object")
    ? resp.probabilities : {};

let confidence = "";
const pvals = Object.values(probs)
    .map(Number)
    .filter(Number.isFinite);

if (pvals.length > 0) {
    confidence = Math.max(...pvals);
}

const x = Array.isArray(resp.x) ? resp.x : [];

function csv(v) {
    if (v === undefined || v === null) return "";
    const s = String(v);
    if (s.includes(",") || s.includes('"') || s.includes("\n")) {
        return '"' + s.replace(/"/g, '""') + '"';
    }
    return s;
}

const ts =
    (msg.meta && msg.meta.t1)
    ? new Date(msg.meta.t1).toISOString()
    : new Date().toISOString();

const row = [
    ts,
    (msg.meta && msg.meta.run_id) || "",
    msg._msgid || "",

    (msg.meta && msg.meta.replay_seq !== undefined)
        ? msg.meta.replay_seq : "",

    (msg.meta && msg.meta.source_line !== undefined)
        ? msg.meta.source_line : "",

    (msg.meta && msg.meta.source_epoch_ms !== undefined)
        ? msg.meta.source_epoch_ms : "",

    (msg.meta && msg.meta.raw_slots_bits !== undefined)
        ? msg.meta.raw_slots_bits : "",

    "S6",
    (msg.meta && msg.meta.scenario) || "",
    resp.execution_site || "",
    (msg.meta && msg.meta.mode) || "",

    msg.statusCode || "",
    (msg.meta && msg.meta.latency_ms !== undefined)
        ? msg.meta.latency_ms : "",

    (resp.service_inference_ms !== undefined)
        ? resp.service_inference_ms : "",

    (resp.prediction !== undefined)
        ? resp.prediction : "",

    confidence,
    JSON.stringify(probs),
    resp.model_sha256 || "",

    (msg.meta && msg.meta.gt_occ !== undefined)
        ? msg.meta.gt_occ : "",

    (msg.meta && msg.meta.gt_free !== undefined)
        ? msg.meta.gt_free : "",

    x.length > 0 ? x[0] : "",
    x.length > 1 ? x[1] : "",
    x.length > 2 ? x[2] : "",
    x.length > 3 ? x[3] : "",
    x.length > 4 ? x[4] : "",
    x.length > 5 ? x[5] : ""
];

msg.payload = row.map(csv).join(",") + "\n";
return msg;

const line =
    String(msg.payload || "")
    .split(/\r?\n/)[0]
    .trim();

const p = line.split(/\s+/);

if (p[0] !== "cpu") {
    return null;
}

const v =
    p.slice(1, 9)
     .map(Number);

if (
    v.length < 8 ||
    !v.every(Number.isFinite)
) {
    return null;
}

const total =
    v.reduce(
        (a, b) => a + b,
        0
    );

const idle =
    v[3] + v[4];

const prevTotal =
    Number(
        flow.get(
            "s7_cpu_prev_total"
        )
    );

const prevIdle =
    Number(
        flow.get(
            "s7_cpu_prev_idle"
        )
    );

flow.set(
    "s7_cpu_prev_total",
    total
);

flow.set(
    "s7_cpu_prev_idle",
    idle
);

if (
    !Number.isFinite(prevTotal) ||
    !Number.isFinite(prevIdle)
) {
    return null;
}

const dt =
    total - prevTotal;

const di =
    idle - prevIdle;

if (dt <= 0) {
    return null;
}

let util =
    100 * (dt - di) / dt;

util =
    Math.max(
        0,
        Math.min(
            100,
            util
        )
    );

flow.set(
    "s7_cpu_raw_percent",
    util
);

flow.set(
    "s7_cpu_sample_ts",
    Date.now()
);

return null;

msg.meta =
    msg.meta || {};

const seq =
    Number(
        msg.meta.replay_seq
    );

if (!Number.isFinite(seq)) {
    node.error(
        "S7 missing replay_seq",
        msg
    );
    return null;
}

let n =
    Number(
        flow.get(
            "s7_decision_number"
        )
    );

if (seq === 1) {

    n = 0;

    flow.set(
        "s7_current_site",
        "edge"
    );

    flow.set(
        "s7_edge_healthy",
        true
    );

    /*
     * Final-run procedure performs
     * external edge/cloud preflight
     * before replay is permitted.
     */
    flow.set(
        "s7_cloud_healthy",
        true
    );

    flow.set(
        "s7_L_edge_hat",
        191.113
    );

    flow.set(
        "s7_L_cloud_hat",
        486.772
    );

    flow.set(
        "s7_CPU_hat",
        null
    );

    flow.set(
        "s7_dwell_count",
        0
    );

    flow.set(
        "s7_e2c_count",
        0
    );

    flow.set(
        "s7_c2e_count",
        0
    );

    flow.set(
        "s7_logger_header_written",
        false
    );

    flow.set(
        "s7_probe_header_written",
        false
    );

    const rid =
        "S7_" +
        new Date()
        .toISOString()
        .replace(
            /[:.]/g,
            "-"
        );

    flow.set(
        "s7_run_id",
        rid
    );
}

if (!Number.isFinite(n)) {
    n = 0;
}

n += 1;

if (
    n < 1 ||
    n > 289
) {
    node.error(
        "S7 decision outside 1..289",
        msg
    );
    return null;
}

flow.set(
    "s7_decision_number",
    n
);

const originalPayload =
    JSON.parse(
        JSON.stringify(
            msg.payload || {}
        )
    );

msg.s7 = {
    decision_number: n,
    replay_seq: seq,

    run_id:
        flow.get(
            "s7_run_id"
        ),

    ai_payload:
        originalPayload
};

msg.payload = {
    decision_number: n,
    replay_seq: seq
};

/*
 * Remove any legacy cloud/API header before
 * communicating with the local load controller.
 */
msg.headers = {
    "Content-Type":
        "application/json"
};

msg.method = "POST";

delete msg.requestTimeout;
delete msg.statusCode;
delete msg.error;

return msg;

const reason =
    (
        msg.error &&
        msg.error.message
    )
    ? msg.error.message
    : "load-controller request failed";

flow.set(
    "s7_abort_reason",
    reason
);

node.error(
    "S7 ABORT: " + reason,
    msg
);

return null;

const perf =
    global.get("perf");

const ALPHA = 0.20;
const U_LOW = 55;
const U_HIGH = 80;
const DELTA0 = 295.659;
const H = 45;
const M = 3;
const D = 10;

const ack =
    (
        msg.payload &&
        typeof msg.payload === "object"
    )
    ? msg.payload
    : {};

if (
    Number(msg.statusCode) !== 200 ||
    ack.ok !== true ||
    Number(ack.decision_number)
        !== Number(
            msg.s7.decision_number
        ) ||
    Number(ack.replay_seq)
        !== Number(
            msg.s7.replay_seq
        )
) {
    node.error(
        "S7 load-controller ACK invalid",
        msg
    );

    return null;
}

/*
 * Experimental CPU-load orchestration has now
 * completed for this decision.
 *
 * S7 measured latency starts HERE, so worker
 * start/stop management and the /decision call
 * are excluded from performance latency.
 */
msg.s7.performance_t0_mono =
    perf.now();

msg.s7.load_phase =
    ack.phase || "";

msg.s7.load_phase_changed =
    ack.phase_changed === true;

msg.s7.load_target_workers =
    Number(
        ack.target_worker_count
    );

const cpuRaw =
    Number(
        flow.get(
            "s7_cpu_raw_percent"
        )
    );

const cpuTs =
    Number(
        flow.get(
            "s7_cpu_sample_ts"
        )
    );

if (
    !Number.isFinite(cpuRaw) ||
    !Number.isFinite(cpuTs) ||
    (Date.now() - cpuTs) > 2000
) {
    node.error(
        "S7 CPU sample missing or stale",
        msg
    );

    return null;
}

/*
 * s7_CPU_hat=null denotes an uninitialized CPU EWMA.
 *
 * Number(null) is 0 in JavaScript. Therefore null and
 * undefined must be handled before numeric conversion
 * so that the first valid CPU sample initializes the
 * EWMA directly, as required by frozen Policy V2.
 */
const cpuHatState =
    flow.get(
        "s7_CPU_hat"
    );

let cpuHat =
    (
        cpuHatState === null ||
        cpuHatState === undefined
    )
    ? NaN
    : Number(cpuHatState);

if (!Number.isFinite(cpuHat)) {
    cpuHat = cpuRaw;
}
else {
    cpuHat =
        ALPHA * cpuRaw +
        (1 - ALPHA) * cpuHat;
}

flow.set(
    "s7_CPU_hat",
    cpuHat
);

let Ledge =
    Number(
        flow.get(
            "s7_L_edge_hat"
        )
    );

let Lcloud =
    Number(
        flow.get(
            "s7_L_cloud_hat"
        )
    );

if (!Number.isFinite(Ledge)) {
    Ledge = 191.113;
}

if (!Number.isFinite(Lcloud)) {
    Lcloud = 486.772;
}

let normalized =
    (
        cpuHat - U_LOW
    ) /
    (
        U_HIGH - U_LOW
    );

normalized =
    Math.max(
        0,
        Math.min(
            1.5,
            normalized
        )
    );

const cpuPenalty =
    DELTA0 * normalized;

const edgeCost =
    Ledge + cpuPenalty;

let edgeHealthy =
    flow.get(
        "s7_edge_healthy"
    ) !== false;

let cloudHealthy =
    flow.get(
        "s7_cloud_healthy"
    ) !== false;

const cloudCost =
    cloudHealthy
    ? Lcloud
    : null;

let current =
    flow.get(
        "s7_current_site"
    ) || "edge";

const previous =
    current;

let dwell =
    Number(
        flow.get(
            "s7_dwell_count"
        )
    );

if (!Number.isFinite(dwell)) {
    dwell = 0;
}

let e2c =
    Number(
        flow.get(
            "s7_e2c_count"
        )
    );

let c2e =
    Number(
        flow.get(
            "s7_c2e_count"
        )
    );

if (!Number.isFinite(e2c)) {
    e2c = 0;
}

if (!Number.isFinite(c2e)) {
    c2e = 0;
}

let switched = false;
let reason = "none";

if (
    current === "edge" &&
    !edgeHealthy &&
    cloudHealthy
) {
    current = "cloud";
    switched = true;
    reason =
        "health_failover_edge_to_cloud";
}
else if (
    current === "cloud" &&
    !cloudHealthy &&
    edgeHealthy
) {
    current = "edge";
    switched = true;
    reason =
        "health_failover_cloud_to_edge";
}
else if (current === "edge") {

    const candidate =
        cloudHealthy &&
        (
            Lcloud + H
            < edgeCost
        );

    e2c =
        candidate
        ? e2c + 1
        : 0;

    c2e = 0;

    if (
        e2c >= M &&
        dwell >= D
    ) {
        current = "cloud";
        switched = true;

        reason =
            "cost_hysteresis_edge_to_cloud";
    }
}
else {

    const candidate =
        edgeHealthy &&
        cloudHealthy &&
        (
            edgeCost + H
            < Lcloud
        );

    c2e =
        candidate
        ? c2e + 1
        : 0;

    e2c = 0;

    if (
        c2e >= M &&
        dwell >= D
    ) {
        current = "edge";
        switched = true;

        reason =
            "cost_hysteresis_cloud_to_edge";
    }
}

let superiorityCount;

if (switched) {

    dwell = 0;
    e2c = 0;
    c2e = 0;

    superiorityCount = 0;
}
else {

    superiorityCount =
        current === "edge"
        ? e2c
        : c2e;

    dwell += 1;
}

flow.set(
    "s7_current_site",
    current
);

flow.set(
    "s7_dwell_count",
    dwell
);

flow.set(
    "s7_e2c_count",
    e2c
);

flow.set(
    "s7_c2e_count",
    c2e
);

msg.s7.previous_site =
    previous;

msg.s7.selected_site =
    current;

msg.s7.switch_occurred =
    switched;

msg.s7.switch_reason =
    reason;

msg.s7.edge_CPU_raw_percent =
    cpuRaw;

msg.s7.edge_CPU_EWMA_percent =
    cpuHat;

msg.s7.edge_latency_EWMA_ms =
    Ledge;

msg.s7.cloud_latency_EWMA_ms =
    Lcloud;

msg.s7.CPU_penalty_ms =
    cpuPenalty;

msg.s7.edge_cost_ms =
    edgeCost;

msg.s7.cloud_cost_ms =
    cloudCost;

msg.s7.edge_healthy_decision =
    edgeHealthy;

msg.s7.cloud_healthy_decision =
    cloudHealthy;

msg.s7.dwell_count =
    dwell;

msg.s7.superiority_count =
    superiorityCount;

msg.s7.primary_attempt_site =
    current;

msg.s7.primary_attempt_status =
    "";

msg.s7.primary_attempt_latency_ms =
    "";

msg.s7.primary_http_status =
    "";

msg.s7.fallback_used =
    false;

msg.s7.fallback_site =
    "";

msg.s7.fallback_status =
    "";

msg.s7.fallback_latency_ms =
    "";

msg.s7.attempt_kind =
    "primary";

msg.s7.attempt_site =
    current;

msg.s7.attempt_t0_mono =
    perf.now();

msg.payload =
    JSON.parse(
        JSON.stringify(
            msg.s7.ai_payload
        )
    );

msg.headers = {
    "Content-Type":
        "application/json"
};

msg.method = "POST";

delete msg.statusCode;
delete msg.error;

if (current === "cloud") {

    msg.requestTimeout =
        1500;

    return [
        null,
        msg
    ];
}

delete msg.requestTimeout;

return [
    msg,
    null
];

const perf =
    global.get("perf");

const MODEL =
    "f400fb75d4ef47f0359129e4ac96cad49" +
    "ae4c1694f33326014d54b977fe2855e";

const ALPHA = 0.20;

msg.s7 =
    msg.s7 || {};

const site =
    msg.s7.attempt_site;

const kind =
    msg.s7.attempt_kind;

const t0 =
    Number(
        msg.s7.attempt_t0_mono
    );

const attemptMs =
    Number.isFinite(t0)
    ? perf.now() - t0
    : null;

let r =
    msg.payload;

if (typeof r === "string") {

    try {
        r = JSON.parse(r);
    }
    catch (e) {
        r = {};
    }
}

if (
    !r ||
    typeof r !== "object"
) {
    r = {};
}

const status =
    Number(
        msg.statusCode
    );

const success =
    !msg.error &&
    status === 200 &&
    r.prediction !== undefined &&
    r.model_sha256 === MODEL &&
    r.execution_site === site;


function updateLatency(
    which,
    observation
) {

    const key =
        which === "edge"
        ? "s7_L_edge_hat"
        : "s7_L_cloud_hat";

    let before =
        Number(
            flow.get(key)
        );

    if (!Number.isFinite(before)) {

        before =
            which === "edge"
            ? 191.113
            : 486.772;
    }

    const after =
        ALPHA * observation +
        (1 - ALPHA) * before;

    flow.set(
        key,
        after
    );

    return {
        before,
        after
    };
}


function setHealthy(
    which,
    value
) {

    flow.set(
        which === "edge"
        ? "s7_edge_healthy"
        : "s7_cloud_healthy",
        value
    );
}


function prepareAttempt(
    which,
    attemptKind
) {

    msg.s7.attempt_site =
        which;

    msg.s7.attempt_kind =
        attemptKind;

    msg.s7.attempt_t0_mono =
        perf.now();

    msg.payload =
        JSON.parse(
            JSON.stringify(
                msg.s7.ai_payload
            )
        );

    msg.headers = {
        "Content-Type":
            "application/json"
    };

    msg.method = "POST";

    /*
     * Important after a failed/caught previous
     * attempt: remove its failure state before
     * sending the fallback.
     */
    delete msg.error;
    delete msg.statusCode;
    delete msg.responseUrl;

    if (which === "cloud") {
        msg.requestTimeout = 1500;
    }
    else {
        delete msg.requestTimeout;
    }
}


/*
 * Non-selected-site probe.
 */
if (kind === "probe") {

    const key =
        site === "edge"
        ? "s7_L_edge_hat"
        : "s7_L_cloud_hat";

    let before =
        Number(
            flow.get(key)
        );

    if (!Number.isFinite(before)) {
        before =
            site === "edge"
            ? 191.113
            : 486.772;
    }

    let after =
        before;

    if (
        success &&
        Number.isFinite(attemptMs)
    ) {

        const u =
            updateLatency(
                site,
                attemptMs
            );

        before =
            u.before;

        after =
            u.after;

        setHealthy(
            site,
            true
        );
    }
    else {

        setHealthy(
            site,
            false
        );
    }

    msg.s7.probe_success =
        success;

    msg.s7.probe_http_status =
        Number.isFinite(status)
        ? status
        : "";

    msg.s7.probe_latency_ms =
        Number.isFinite(attemptMs)
        ? attemptMs
        : "";

    msg.s7.probe_service_inference_ms =
        (
            success &&
            r.service_inference_ms !== undefined
        )
        ? r.service_inference_ms
        : "";

    msg.s7.probe_prediction =
        success
        ? r.prediction
        : "";

    msg.s7.probe_model_sha256 =
        success
        ? r.model_sha256
        : "";

    msg.s7.probe_latency_EWMA_before =
        before;

    msg.s7.probe_latency_EWMA_after =
        after;

    msg.s7.probe_health_after =
        site === "edge"
        ? (
            flow.get(
                "s7_edge_healthy"
            ) !== false
          )
        : (
            flow.get(
                "s7_cloud_healthy"
            ) !== false
          );

    msg.payload = r;

    return [
        null,
        null,
        null,
        msg
    ];
}


/*
 * Actual S7 inference attempt.
 */
if (kind === "primary") {

    msg.s7.primary_attempt_status =
        success
        ? "success"
        : "failed";

    msg.s7.primary_attempt_latency_ms =
        Number.isFinite(attemptMs)
        ? attemptMs
        : "";

    msg.s7.primary_http_status =
        Number.isFinite(status)
        ? status
        : "";
}
else {

    msg.s7.fallback_status =
        success
        ? "success"
        : "failed";

    msg.s7.fallback_latency_ms =
        Number.isFinite(attemptMs)
        ? attemptMs
        : "";
}


if (success) {

    /*
     * For a normal primary decision use the
     * measured S7 policy-to-result latency.
     *
     * For fallback/probe observations use only
     * that site's individual HTTP attempt.
     */
    let observation =
        attemptMs;

    if (kind === "primary") {

        const p0 =
            Number(
                msg.s7.performance_t0_mono
            );

        if (Number.isFinite(p0)) {

            observation =
                perf.now() - p0;
        }
    }

    if (Number.isFinite(observation)) {

        updateLatency(
            site,
            observation
        );
    }

    setHealthy(
        site,
        true
    );

    if (kind === "fallback") {

        const old =
            flow.get(
                "s7_current_site"
            ) || "";

        if (old !== site) {

            flow.set(
                "s7_current_site",
                site
            );

            flow.set(
                "s7_dwell_count",
                0
            );

            flow.set(
                "s7_e2c_count",
                0
            );

            flow.set(
