    const edgeHealthy =
        flow.get(
            "s7_edge_healthy"
        ) !== false;

    const cloudHealthy =
        flow.get(
            "s7_cloud_healthy"
        ) !== false;

    if (
        site === "cloud" &&
        edgeHealthy
    ) {

        msg.s7.fallback_used =
            true;

        msg.s7.fallback_site =
            "edge";

        prepareAttempt(
            "edge",
            "fallback"
        );

        return [
            null,
            msg,
            null,
            null
        ];
    }

    if (
        site === "edge" &&
        cloudHealthy
    ) {

        msg.s7.fallback_used =
            true;

        msg.s7.fallback_site =
            "cloud";

        prepareAttempt(
            "cloud",
            "fallback"
        );

        return [
            null,
            null,
            msg,
            null
        ];
