msg.s7.final_success =
    false;

msg.s7.final_execution_site =
    "";

msg.s7.final_http_status =
    Number.isFinite(status)
    ? status
    : "";

msg.s7.final_response = {};

msg.payload = {};

return [
    msg,
    null,
    null,
    null
];

const perf =
    global.get("perf");

msg.s7 =
    msg.s7 || {};

const start =
    Number(
        msg.s7.performance_t0_mono
