        typeof r.probabilities
        === "object"
    )
    ? r.probabilities
    : {};

msg.s7.probabilities =
    probs;

const vals =
    Object.values(probs)
    .map(Number)
    .filter(Number.isFinite);

msg.s7.confidence =
    vals.length
    ? Math.max(...vals)
    : "";

msg.s7.model_sha256 =
    r.model_sha256 || "";

msg.s7.edge_healthy_final =
    flow.get(
