const perf =
    global.get("perf");

msg.s7 =
    msg.s7 || {};

const n =
    Number(
        msg.s7.decision_number
    );

if (
    !Number.isFinite(n) ||
    n % 10 !== 0
) {

    return [
        null,
        null
    ];
}

const current =
    flow.get(
        "s7_current_site"
    ) || "edge";

const probeSite =
    current === "edge"
    ? "cloud"
    : "edge";

msg.s7.probe_site =
    probeSite;

msg.s7.probe_for_current_site =
    current;

msg.s7.probe_health_before =
    probeSite === "edge"
