function csv(v) {

    if (
        v === undefined ||
        v === null
    ) {
        return "";
    }

    const s =
        String(v);

    if (
        s.includes(",") ||
        s.includes('"') ||
        s.includes("\n")
    ) {

        return (
            '"' +
            s.replace(
                /"/g,
                '""'
            ) +
            '"'
        );
    }

    return s;
}

const columns = [
    "timestamp",
    "run_id",
    "decision_number",
    "replay_seq",
    "probe_site",
    "probe_for_current_site",
    "probe_success",
    "probe_http_status",
    "probe_latency_ms",
    "probe_service_inference_ms",
    "prediction",
    "model_sha256",
    "site_latency_EWMA_before",
    "site_latency_EWMA_after",
    "site_health_before",
    "site_health_after",
    "included_in_performance_dataset"
];

const values = [
    new Date().toISOString(),

    msg.s7.run_id || "",

    msg.s7.decision_number ?? "",

    msg.s7.replay_seq ?? "",

    msg.s7.probe_site || "",

    msg.s7.probe_for_current_site || "",

    msg.s7.probe_success
        ? 1
        : 0,

    msg.s7.probe_http_status ?? "",

    msg.s7.probe_latency_ms ?? "",

    msg.s7.probe_service_inference_ms ?? "",

    msg.s7.probe_prediction || "",

    msg.s7.probe_model_sha256 || "",

    msg.s7.probe_latency_EWMA_before ?? "",

    msg.s7.probe_latency_EWMA_after ?? "",

    msg.s7.probe_health_before
        ? 1
        : 0,

    msg.s7.probe_health_after
        ? 1
        : 0,

    "NO"
];

